function ENT:Initialize()
self:SetModel("models/props_lab/box01a.mdl");
self:PhysicsInit(SOLID_VPHYSICS);

self:SetMoveType(MOVETYPE_VPHYSICS);
self:SetSolid(SOLID_VPHYSICS);

self:SetDTInt(1, 4);
self:SetDTString(2, "none")
end;

function ENT:OnTakeDamage(dmginfo)
self:VisualEffect();
self:EmitSound("physics/cardboard/cardboard_box_break3.wav");
self:Remove()
end;

function ENT:SpawnFunction(ply, trace)
local ent = ents.Create("fs_fertilizer");
ent:SetPos(trace.HitPos + trace.HitNormal * 8);
ent:Spawn();
ent:Activate();
return ent;
end;

function ENT:Think()
if (!self.nextSec or CurTime() >= self.nextSec) then
local fertilizerTarget = FS_Utils.GetFertilizerTarget and FS_Utils.GetFertilizerTarget(self) or nil
if IsValid(fertilizerTarget) then
local fertilizerResult = FS_Utils.ApplyFertilizer(fertilizerTarget)
if (fertilizerResult == 1) then
self:SetDTInt(1, 1);
self:SetDTString(2, tostring(fertilizerTarget:EntIndex()));
self:EmitSound("physics/cardboard/cardboard_box_break3.wav");
self:VisualEffect();
elseif (fertilizerResult == 2) then
self:SetDTInt(1, 2);
elseif (fertilizerResult == 3) then
self:SetDTInt(1, 3);
else
self:SetDTInt(1, 4);
end;
else
self:SetDTInt(1, 4);
self:SetDTString(2, "none")
end;
self.nextSec = CurTime() + FS_Utils.SlowThinkInterval;
end;

self:NextThink(CurTime() + FS_Utils.SlowThinkInterval);
return true;
end;

function ENT:VisualEffect()
local effectData = EffectData();
effectData:SetStart(self:GetPos());
effectData:SetOrigin(self:GetPos());
effectData:SetScale(8);
util.Effect("GlassImpact", effectData, true, true);
self:Remove();
end;

