function ENT:PhysicsCollide(data, phys)
if not data or not IsValid(data.HitEntity) or data.DeltaTime <= 0.1 then
return
end

local hitClass = data.HitEntity:GetClass();
if hitClass == "fs_lemon" then
self:SetDTFloat(5, math.Clamp(self:GetDTFloat(5)+FS_Baby_Lemon_SpeedIncome, 0, FS_Baby_MaxSpeed));
self:EmitSound("npc/headcrab_poison/ph_poisonbite2.wav");
data.HitEntity:VisualEffect();
end;
if hitClass == "fs_tomato" then
self:SetDTFloat(6, math.Clamp(self:GetDTFloat(6)+FS_Baby_Tomato_RadiusIncome, 0, FS_Baby_MaxRadius));
self:EmitSound("npc/headcrab_poison/ph_poisonbite2.wav");
data.HitEntity:VisualEffect();
end;
if hitClass == "fs_potato" then
self:SetHealth(math.Clamp(self:Health()+FS_Baby_Potato_HealthIncome, 0, FS_Baby_MaxHealth));
self:EmitSound("npc/headcrab_poison/ph_poisonbite2.wav");
data.HitEntity:VisualEffect();
end;
if hitClass == "fs_apple" then
self:SetDTFloat(7, math.Clamp(self:GetDTFloat(7)+FS_Baby_Apple_HungerIncome, 0, FS_Baby_StartHunger));
self:EmitSound("npc/headcrab_poison/ph_poisonbite2.wav");
data.HitEntity:VisualEffect();
end;
end;

function ENT:Think()
local curTime = CurTime();
if (!self.nextAttack or curTime >= self.nextAttack) then
if self:GetDTBool(8) then
local position = self:GetPos();
local radiusSqr = self:GetDTFloat(6) * self:GetDTFloat(6);
local ownerName = self:GetDTString(1);
local target = nil;
local closestDistance = radiusSqr;

for _, playerEntity in ipairs(player.GetAll()) do
if IsValid(playerEntity) and playerEntity:Alive() and playerEntity:Nick() != ownerName then
local distance = position:DistToSqr(playerEntity:GetPos());
if distance <= closestDistance then
target = playerEntity;
closestDistance = distance;
end
end
end

if IsValid(target) then
self:SetAngles((target:LocalToWorld(target:OBBCenter())-position):Angle());
local physicsObject = FS_Utils.GetPhysicsObject(self);
if physicsObject then
physicsObject:SetVelocity((self:GetForward() * self:GetDTFloat(5))+Vector(0, 0, 64));
physicsObject:Wake();
end
self:EmitSound("npc/fast_zombie/leap1.wav");
end

self.nextAttack = curTime + 1.5;
end;
end;

if (!self.nextHunger or curTime >= self.nextHunger) then
local hungerCost = self:GetDTBool(8) and FS_Baby_HungerConsumptionPerSec or (FS_Baby_HungerConsumptionPerSec / 4);
local newHunger = self:GetDTFloat(7) - hungerCost;
if (newHunger <= 0) then
self:Remove();
return
end;

