function spawnSalesmanPos(ply, cmd, args)
if (ply:IsAdmin() or ply:IsSuperAdmin()) then
local fileSalesmanName = args[1];

if !fileSalesmanName then
ply:SendLua("local tab = {Color(213,213,25),[[[Farm System] ]],Color(255,255,255),[[Choose a name for your salesman.]]}chat.AddText(unpack(tab))");
return;
end;

if file.Exists( "fs/"..string.lower(game.GetMap()).."/salesman_".. fileSalesmanName ..".txt", "DATA") then
ply:SendLua("local tab = {Color(213,213,25), [[[Farm System] ]],Color(255,255,255),[[This name is alredy in use, choose another one or type 'fs_salesman_remove "..fileSalesmanName.."' in console to remove this one.]] } chat.AddText(unpack(tab))");
return;
end;

local salesmanVector = string.Explode(" ", tostring(ply:GetEyeTrace().HitPos));
local salesmanAngles = string.Explode(" ", tostring(ply:GetAngles()+Angle(0, -180, 0)));

--[[
local salesman = ents.Create("fs_salesman");
salesman:SetPos(ply:GetEyeTrace().HitPos);
salesman:SetAngles(ply:GetAngles()+Angle(0, -180, 0));
salesman:Spawn();
]]--

file.Write("fs/"..string.lower(game.GetMap()).."/salesman_".. fileSalesmanName ..".txt", ""..(salesmanVector[1]).." "..(salesmanVector[2]).." "..(salesmanVector[3]).." "..(salesmanAngles[1]).." "..(salesmanAngles[2]).." "..(salesmanAngles[3]).."", "DATA");
ply:SendLua("local tab = {Color(213,213,25),[[[Farm System] ]],Color(255,255,255),[[New pos for the salesman has been set. Restart your server now!]]}chat.AddText(unpack(tab))");
else
ply:SendLua("local tab = {Color(213,213,25),[[[Farm System] ]],Color(255,255,255),[[Only admins and superadmins can perform this action.]]}chat.AddText(unpack(tab))");
end;
end;
concommand.Add("fs_salesman_spawn", spawnSalesmanPos);

function removeSalesmanPos(ply, cmd, args)
if (ply:IsAdmin() or ply:IsSuperAdmin()) then
local fileVaultName = args[1];

if !fileVaultName then
ply:SendLua("local tab = {Color(213,213,25),[[[Farm System] ]],Color(255,255,255),[[Please enter a name of file!]] } chat.AddText(unpack(tab))");
