local autoPlantSlotInsetRatio = 0.18
local autoPlantSlotInsetMin = 20
local autoPlantSlotRandomOffset = 6
local immediateManagementThinkInterval = 0.05
local assignedSeedHorizontalTolerance = 36
local assignedSeedVerticalTolerance = 120

local function getDirtPatchTimerName(dirtPatch)
return "FS_DirtPatchManage_" .. dirtPatch:EntIndex()
end

local function setCachedNWInt(entity, key, value)
entity.fsNetworkState = entity.fsNetworkState or {}
local clampedValue = math.floor(tonumber(value) or 0)
if entity.fsNetworkState[key] == clampedValue then
return false
end

entity.fsNetworkState[key] = clampedValue
entity:SetNWInt(key, clampedValue)
return true
end

local function anglesChanged(leftAngle, rightAngle)
if not leftAngle or not rightAngle then
return true
end

return math.abs(math.AngleDifference(leftAngle.p, rightAngle.p)) > 0.1
or math.abs(math.AngleDifference(leftAngle.y, rightAngle.y)) > 0.1
or math.abs(math.AngleDifference(leftAngle.r, rightAngle.r)) > 0.1
end

local function getGridCoordinate(index, gridSize, minValue, maxValue)
if gridSize <= 1 then
return (minValue + maxValue) * 0.5
end

return minValue + ((index - 1) / (gridSize - 1)) * (maxValue - minValue)
end

local function getEntityWorldTransform(entity)
if not IsValid(entity) then
return nil, nil
end

local parentEntity = entity:GetParent()
if not IsValid(parentEntity) then
return entity:GetPos(), entity:GetAngles()
end

return LocalToWorld(entity:GetLocalPos(), entity:GetLocalAngles(), parentEntity:GetPos(), parentEntity:GetAngles())
end

function ENT:Initialize()
self:SetModel("models/hunter/plates/plate2x2.mdl");
self:SetMaterial("models/props_wasteland/dirtwall001a");
self:PhysicsInit(SOLID_VPHYSICS);
self:SetMoveType(MOVETYPE_VPHYSICS);
self:SetSolid(SOLID_VPHYSICS);
self:SetUseType(SIMPLE_USE);
self.fsSeedSlots = {};
self.fsNetworkState = {}
self.fsManagementTimerName = getDirtPatchTimerName(self)
self.fsManagementTimerInterval = nil
setCachedNWInt(self, "FSOccupiedSlots", 0);
setCachedNWInt(self, "FSRemainingSeedSlots", self.SeedCapacity);

local physicsObject = FS_Utils.GetPhysicsObject(self);
if physicsObject then
physicsObject:SetMass(140);
physicsObject:Wake();
end
FS_Utils.RegisterTrackedDamageEntity(self);
FS_Utils.SetDirtPatchCarryState(self, false);
self.fsLastManagedPosition = self:GetPos();
self.fsLastManagedAngles = self:GetAngles();

self:SetPos(self:GetPos()+self:GetUp()*1.5);

timer.Simple(0, function()
if not IsValid(self) then
return
end

self:RequestManagementCheck(true)
end)
end;

function ENT:GetManagementTimerName()
self.fsManagementTimerName = self.fsManagementTimerName or getDirtPatchTimerName(self)
return self.fsManagementTimerName
end

function ENT:StopManagementTimer()
local timerName = self:GetManagementTimerName()
if timer.Exists(timerName) then
timer.Remove(timerName)
end

self.fsManagementTimerInterval = nil
return true
end

function ENT:EnsureManagementTimer(interval)
local thinkInterval = math.max(tonumber(interval) or autoPlantThinkInterval, immediateManagementThinkInterval)
local timerName = self:GetManagementTimerName()
if timer.Exists(timerName) and self.fsManagementTimerInterval == thinkInterval then
return true
end

timer.Remove(timerName)
self.fsManagementTimerInterval = thinkInterval
timer.Create(timerName, thinkInterval, 0, function()
if not IsValid(self) then
timer.Remove(timerName)
return
end

if not self:ProcessManagementCycle() then
self:StopManagementTimer()
end
end)

return true
end

function ENT:RequestManagementCheck(immediate)
if self.fsRemovingSeedContents then
return false
end

local nextInterval = immediate == true and immediateManagementThinkInterval or autoPlantThinkInterval
return self:EnsureManagementTimer(nextInterval)
end

function ENT:RequestNearbyAutoFarmCheck()
if not FS_Utils or not FS_Utils.WakeOwnedAutoFarms then
return 0
end

return FS_Utils.WakeOwnedAutoFarms(self:GetNWString("FSOwnerSteamID64", ""), self:GetPos())
end

function ENT:ClearSeedSlot(slotIndex, seed)
local clearedSlot = false
if self.fsSeedSlots and self.fsSeedSlots[slotIndex] == seed then
self.fsSeedSlots[slotIndex] = nil;
clearedSlot = true
end

if IsValid(seed) and seed.fsDirtPatch == self then
if self.fsRemovingSeedContents then
seed.fsDirtPatch = nil;
seed.fsDirtPatchSlot = nil;
seed.fsDirtPatchSlotOffset = nil;
return;
end

local worldPosition, worldAngles = getEntityWorldTransform(seed);
if seed:GetParent() == self then
seed:SetParent(nil);
if worldPosition then
seed:SetPos(worldPosition);
end
if worldAngles then
seed:SetAngles(worldAngles);
end
end

if seed:GetMoveType() == MOVETYPE_NONE then
seed:SetMoveType(MOVETYPE_VPHYSICS);
FS_Utils.SetPhysicsMotion(seed, false);
end

seed.fsDirtPatch = nil;
seed.fsDirtPatchSlot = nil;
seed.fsDirtPatchSlotOffset = nil;
end

if clearedSlot and not self.fsProcessingManagementCycle and not self.fsRemovingSeedContents then
self:RequestManagementCheck(true)
self:RequestNearbyAutoFarmCheck()
end
end;

function ENT:RemoveSeedSlotContents(slotIndex, seed)
if self.fsSeedSlots and self.fsSeedSlots[slotIndex] == seed then
self.fsSeedSlots[slotIndex] = nil;
end

if not IsValid(seed) then
return;
end

if FS_Utils and FS_Utils.GetSeedChildren then
for childIndex, child in pairs(FS_Utils.GetSeedChildren(seed)) do
if IsValid(child) then
child:Remove();
end

if seed.fsSeedChildren then
seed.fsSeedChildren[childIndex] = nil;
end
end
end

seed.fsDirtPatch = nil;
seed.fsDirtPatchSlot = nil;
seed.fsDirtPatchSlotOffset = nil;
seed:Remove();
end;

function ENT:IsAssignedSeedStillInPatch(seed, slotIndex)
if not IsValid(seed) or seed.fsDirtPatch ~= self or seed.fsDirtPatchSlot ~= slotIndex then
return false;
end

if seed:GetParent() == self then
local localPosition = seed:GetLocalPos();
local slotPosition = self:GetSlotLocalPosition(slotIndex, seed);
return math.abs(localPosition.x - slotPosition.x) <= assignedSeedHorizontalTolerance
and math.abs(localPosition.y - slotPosition.y) <= assignedSeedHorizontalTolerance
and math.abs(localPosition.z - slotPosition.z) <= assignedSeedVerticalTolerance;
end

return self:IsSeedInsideBounds(seed);
end;

function ENT:CleanupSeedSlots()
if not self.fsSeedSlots then
self.fsSeedSlots = {};
end

if self.fsRemovingSeedContents then
setCachedNWInt(self, "FSOccupiedSlots", 0);
setCachedNWInt(self, "FSRemainingSeedSlots", self.SeedCapacity);
return 0;
end

local occupiedSlots = 0;
for slotIndex = 1, self.SeedCapacity do
local seed = self.fsSeedSlots[slotIndex];
if self:IsAssignedSeedStillInPatch(seed, slotIndex) then
occupiedSlots = occupiedSlots + 1;
else
self:ClearSeedSlot(slotIndex, seed);
end
end

setCachedNWInt(self, "FSOccupiedSlots", occupiedSlots);
setCachedNWInt(self, "FSRemainingSeedSlots", self.SeedCapacity - occupiedSlots);

return occupiedSlots;
end;

function ENT:GetOpenSlotIndex()
self:CleanupSeedSlots();
return self:GetOpenSlotIndexFast();
end;

function ENT:GetOpenSlotIndexFast()
for slotIndex = 1, self.SeedCapacity do
if not IsValid(self.fsSeedSlots[slotIndex]) then
return slotIndex;
end
end

return nil;
end;

function ENT:CanAcceptSeed(seed)
if IsValid(seed) and seed.fsDirtPatch == self and seed.fsDirtPatchSlot and self.fsSeedSlots[seed.fsDirtPatchSlot] == seed then
return true;
end

return self:GetOpenSlotIndex() ~= nil;
end;

function ENT:GetSlotWorldPosition(slotIndex, seed)
return self:LocalToWorld(self:GetSlotLocalPosition(slotIndex, seed));
end;

function ENT:GetSlotLocalPosition(slotIndex, seed)
local mins, maxs = self:OBBMins(), self:OBBMaxs();
local column = ((slotIndex - 1) % self.GridSize) + 1;
local row = math.floor((slotIndex - 1) / self.GridSize) + 1;
local insetX = math.max((maxs.x - mins.x) * autoPlantSlotInsetRatio, autoPlantSlotInsetMin);
local insetY = math.max((maxs.y - mins.y) * autoPlantSlotInsetRatio, autoPlantSlotInsetMin);
local usableMinX = mins.x + insetX;
local usableMaxX = maxs.x - insetX;
local usableMinY = mins.y + insetY;
local usableMaxY = maxs.y - insetY;
local localX = getGridCoordinate(column, self.GridSize, usableMinX, usableMaxX);
local localY = getGridCoordinate(row, self.GridSize, usableMinY, usableMaxY);
local slotOffset = IsValid(seed) and seed.fsDirtPatchSlotOffset or vector_origin;

return Vector(localX, localY, maxs.z + autoPlantSlotHeight) + slotOffset;
end;

function ENT:AttachSeedToPatch(seed)
if not IsValid(seed) then
return;
end

local localPosition, localAngles = WorldToLocal(seed:GetPos(), seed:GetAngles(), self:GetPos(), self:GetAngles());
if seed:GetParent() ~= self then
seed:SetParent(self);
seed:SetLocalPos(localPosition);
seed:SetLocalAngles(localAngles);
end

if seed:GetMoveType() ~= MOVETYPE_NONE then
seed:SetMoveType(MOVETYPE_NONE);
end
FS_Utils.SetPhysicsMotion(seed, false);
end;

function ENT:SyncAssignedSeeds()
if not self.fsSeedSlots then
return;
end

for slotIndex = 1, self.SeedCapacity do
local seed = self.fsSeedSlots[slotIndex];
if self:IsAssignedSeedStillInPatch(seed, slotIndex) then
self:AttachSeedToPatch(seed);
else
self:ClearSeedSlot(slotIndex, seed);
end
end
end;

function ENT:IsSeedInsideBounds(seed)
if not IsValid(seed) then
return false;
end

local mins, maxs = self:OBBMins(), self:OBBMaxs();
local localPosition = self:WorldToLocal(seed:GetPos());

return localPosition.x >= (mins.x - autoPlantSearchPadding)
and localPosition.x <= (maxs.x + autoPlantSearchPadding)
and localPosition.y >= (mins.y - autoPlantSearchPadding)
and localPosition.y <= (maxs.y + autoPlantSearchPadding)
and localPosition.z >= (mins.z - 24)
and localPosition.z <= (maxs.z + autoPlantSearchHeight);
end;

function ENT:FindCandidateSeeds()
local mins, maxs = self:OBBMins(), self:OBBMaxs();
local searchRadius = math.max(maxs.x - mins.x, maxs.y - mins.y) + autoPlantSearchPadding;
local candidates = {};
local patchPosition = self:GetPos()

for _, entity in ipairs(ents.FindInSphere(patchPosition, searchRadius)) do
local seedState = entity.GetDTInt and entity:GetDTInt(1) or -1;
if FS_Utils.IsSeedEntity(entity)
and entity.GetDTInt
and seedState >= 0
and seedState <= 1
and (not entity.IsPlayerHolding or not entity:IsPlayerHolding())
and not (entity.fsDirtPatch == self and entity.fsDirtPatchSlot and self.fsSeedSlots[entity.fsDirtPatchSlot] == entity)
and (not IsValid(entity.fsDirtPatch) or entity.fsDirtPatch == self)
and self:IsSeedInsideBounds(entity) then
table.insert(candidates, entity);
end
end

if #candidates > 1 then
table.sort(candidates, function(leftSeed, rightSeed)
return patchPosition:DistToSqr(leftSeed:GetPos()) < patchPosition:DistToSqr(rightSeed:GetPos());
end);
end

return candidates;
end;

function ENT:AssignSeedToSlot(seed, slotIndex, skipCleanup)
if not IsValid(seed) or not slotIndex or IsValid(self.fsSeedSlots[slotIndex]) then
return false;
end

self.fsSeedSlots[slotIndex] = seed;
seed.fsDirtPatch = self;
seed.fsDirtPatchSlot = slotIndex;
seed.fsDirtPatchSlotOffset = Vector(math.Rand(-autoPlantSlotRandomOffset, autoPlantSlotRandomOffset), math.Rand(-autoPlantSlotRandomOffset, autoPlantSlotRandomOffset), 0);
seed:CallOnRemove("fs_dirt_patch_slot_" .. self:EntIndex(), function(removedSeed)
if not IsValid(self) then
return;
end

self:ClearSeedSlot(slotIndex, removedSeed);
self:CleanupSeedSlots();
end);

local slotPosition = self:GetSlotWorldPosition(slotIndex, seed);
local planted = false;
if seed:GetDTInt(1) == 0 then
planted = FS_Utils.StartSeedGrowth(seed, slotPosition, Angle(0, self:GetAngles().y, 0));
else
seed.fsPlantAnchorPos = slotPosition;
seed.fsPlantAnchorAngles = Angle(0, self:GetAngles().y, 0);
seed:SetAngles(Angle(0, self:GetAngles().y, 0));
seed:SetPos(slotPosition);
seed:SetDTBool(3, false);
FS_Utils.SetPhysicsMotion(seed, false);
planted = true;
end

if not planted then
self:ClearSeedSlot(slotIndex, seed);
self:CleanupSeedSlots();
return false;
end

self:AttachSeedToPatch(seed);
if not skipCleanup then
self:CleanupSeedSlots();
end
return true;
end;

function ENT:NeedsSeedResync()
local currentPosition = self:GetPos();
local currentAngles = self:GetAngles();
local shouldResync = self.fsDirtPatchHeld == true or self.fsDirtPatchCanMove == true;

if not shouldResync and self.fsLastManagedPosition then
shouldResync = self.fsLastManagedPosition:DistToSqr(currentPosition) > 1 or anglesChanged(self.fsLastManagedAngles, currentAngles);
end

self.fsLastManagedPosition = currentPosition;
self.fsLastManagedAngles = currentAngles;
return shouldResync;
end;

function ENT:SpawnFunction(ply, trace)
if not trace.Hit then
return
end

local ent = ents.Create("fs_dirt_patch");
ent:SetAngles(Angle(0, ply:EyeAngles().y, 0));
ent:SetPos(trace.HitPos + trace.HitNormal * 2);
ent:Spawn();
ent:Activate();
if FS_Utils and FS_Utils.SetEntityOwner then
FS_Utils.SetEntityOwner(ent, ply);
end
return ent;
end;

function ENT:ProcessManagementCycle()
self.fsProcessingManagementCycle = true

local occupiedSlots = self:CleanupSeedSlots();
local shouldResync = self:NeedsSeedResync()
if shouldResync then
self:SyncAssignedSeeds();
occupiedSlots = self:CleanupSeedSlots();
end

if occupiedSlots < self.SeedCapacity then
local openSlotIndex = self:GetOpenSlotIndexFast();
if openSlotIndex then
for _, seed in ipairs(self:FindCandidateSeeds()) do
if not openSlotIndex then
break;
end

if self:AssignSeedToSlot(seed, openSlotIndex, true) then
openSlotIndex = self:GetOpenSlotIndexFast();
end
end

occupiedSlots = self:CleanupSeedSlots();
end
end

self.fsProcessingManagementCycle = nil

if occupiedSlots < self.SeedCapacity then
self:RequestNearbyAutoFarmCheck()
end

local shouldKeepRunning = self.fsDirtPatchHeld == true or self.fsDirtPatchCanMove == true or self.fsDirtPatchCarryPrimedUntil ~= nil
if shouldKeepRunning then
local nextInterval = occupiedSlots >= self.SeedCapacity and fullPatchThinkInterval or autoPlantThinkInterval
self:EnsureManagementTimer(nextInterval)
return true
end

return false
end;

function ENT:OnTakeDamage(dmginfo)
self:TakePhysicsDamage(dmginfo);
end;

function ENT:OnRemove()
self:StopManagementTimer()

if not self.fsSeedSlots then
return;
end

self.fsRemovingSeedContents = true;
for slotIndex, seed in pairs(self.fsSeedSlots) do
self:RemoveSeedSlotContents(slotIndex, seed);
end
self.fsRemovingSeedContents = nil;
end;

