ent:Spawn();
ent:Activate();
return ent;
end;

function ENT:Use(activator, caller)
local curTime = CurTime();
if (!self.nextUse or curTime >= self.nextUse) then
if FS_Utils.CanPlayerUseEntity(activator, self) then
if !activator:KeyDown(IN_SPEED) then
if FS_Hunger_Enabled then
if (GAMEMODE.Version == "2.4.3") then
activator:SetSelfDarkRPVar("Energy", math.Clamp(activator:getDarkRPVar("Energy")+FS_Watermelon_Hunger, 0, 100));
else
activator:setSelfDarkRPVar("Energy", math.Clamp(activator:getDarkRPVar("Energy")+FS_Watermelon_Hunger, 0, 100));
end;
end;
activator:SetHealth(math.Clamp(activator:Health()+FS_Watermelon_Health, 0, 100));
self:EmitSound("npc/barnacle/barnacle_crunch"..math.random(2, 3)..".wav");
self:VisualEffect();
self.nextUse = curTime + 0.5;
elseif activator:KeyDown(IN_SPEED) and FS_Salesman_Enabled then
if (activator:GetDTInt(3) < FS_Watermelon_MaxHold) then
activator:SetDTInt(3, activator:GetDTInt(3)+1);
activator:EmitSound("physics/body/body_medium_impact_soft"..math.random(1, 7)..".wav");
activator:SendLua("local tab={Color(255,255,255),[[You picked up a ]],Color(119,214,25),[[Watermelon]],Color(255,255,255),[[. ["..activator:GetDTInt(3).."/"..FS_Watermelon_MaxHold.."] ]]} chat.AddText(unpack(tab))");
self:VisualEffect();
elseif (activator:GetDTInt(3) >= FS_Watermelon_MaxHold) then
activator:SendLua("LocalPlayer():EmitSound('buttons/lightswitch2.wav')");
activator:SendLua("local tab={Color(255,255,255),[[You reached maximum amount of ]],Color(119,214,25),[[Watermelons]],Color(255,255,255),[[! ["..activator:GetDTInt(3).."/"..FS_Watermelon_MaxHold.."] ]]} chat.AddText(unpack(tab))");
end;
self.nextUse = curTime + 0.5;
end;
end;
end;
end;

function ENT:VisualEffect()
local effectData = EffectData();
effectData:SetStart(self:GetPos());
effectData:SetOrigin(self:GetPos());
effectData:SetScale(8);
util.Effect("GlassImpact", effectData, true, true);
self:Remove();
end;

